  insert into public.profiles (id, full_name, email)
insert into error_codes (code, grade, name, description, light_status) values
  ('ReaderFailure','Warning failure','Card Reader Failure','Card Reader Failure -If the card reader is not connected or the communication fails, this alarm will be triggered and will not affect the normal charging.','Normal state'),
  ('NetworkError','Warning failure','Network Connection Error','Network Connection Error - This fault is triggered if the charger fails to successfully connect to the network.','Blue-green crossing'),
  ('TemperatureWarning','Warning failure','Temperature Warning','Temperature Warning - This fault is triggered if the internal temperature of the charger exceeds the maximum set value.','Normal state'),
  ('VehicleError','Warning failure','Vehicle Diode Detection Error','Vehicle Diode Detection Error - This fault is triggered if the charger detects an anomaly in the EV interface circuit, preventing normal charging.','Normal state'),
  ('ScreenNotConnected','Serious failure','Screen Not Connected','Screen Not Connected - If the charger''s screen enable setting is activated and the screen is not connected, this fault is triggered.','red light'),
  ('GroundFailure','Fatal failure','Ground Fault','Ground Fault - This fault is triggered if the charger detects that the grounding wire is not connected or disconnected.','red light'),
  ('HighTemperature','Fatal failure','High Temperature','High Temperature - This fault is triggered if the temperature of the charger exceeds the maximum set value, causing the charger to immediately stop working.','red light'),
  ('EmergencyStop','Fatal failure','Emergency Stop Fault','Emergency Stop Fault - This fault is triggered if the emergency stop button on the charger is pressed.','red light'),
  ('TamperProtection','Fatal failure','Tamper Protection','Tamper Protection - This fault is triggered if the charger''s enclosure is abnormally opened.','red light'),
  ('PowerLossFailure','Fatal failure','Power Loss Fault','Power Loss Fault - This fault is triggered if the charger experiences an abnormal power loss.','red light'),
  ('LeakCurrentFailure','Fatal failure','Leakage Current Fault','Leakage Current Fault - This fault is triggered if the charger experiences a leakage phenomenon.','red light'),
  ('CTFaultOfPhaseATransformer','Fatal failure','Phase A Sensor Communication Fault','Phase A Sensor Communication Fault - This fault is triggered if the charger''s load balancing is enabled and there is no communication between L1 and the CT sensor.','red light'),
  ('CTFaultOfPhaseBTransformer','Fatal failure','Phase B Sensor Communication Fault','Phase B Sensor Communication Fault - This fault is triggered if the charger''s load balancing is enabled and there is no communication between L2 and the CT sensor.','red light'),
  ('CTFaultOfPhaseCTransformer','Fatal failure','Phase C Sensor Communication Fault','Phase C Sensor Communication Fault - This fault is triggered if the charger''s load balancing is enabled and there is no communication between L3 and the CT sensor.','red light'),
  ('MinCurrentFailure','Fatal failure','Minimum Current of 6A','Minimum Current of 6A - If the PWM duty cycle D of the charger is less than 10%, charging is not allowed to start, triggering this fault.','red light'),
  ('OverCurrentFailure','Power failure','Overcurrent','Overcurrent - This fault is triggered if the charging current of the charger exceeds the maximum set value, causing the charger to immediately stop working.','red light'),
  ('OverVoltage','Power failure','Overvoltage','Overvoltage - This fault is triggered if the charger detects voltage exceeding 253V, causing the charger to immediately stop working.','red light'),
  ('UnderVoltage','Power failure','Undervoltage','Undervoltage - This fault is triggered if the charger detects voltage below 205V, causing the charger to immediately stop working.','red light'),
  ('OpenPENFault','Power failure','OpenPENFault','OpenPENFault - This fault is triggered if the charger detects voltage exceeding 262.2V, causing the charger to immediately stop working and requiring a restart to restore','red light'),
  ('PowerMeterFailure','Power failure','Electric Meter Communication Fault','Electric Meter Communication Fault - This fault is triggered if there is an anomaly in the communication with the charger''s electric meter, causing the charger to immediately stop working.','red light'),
  ('ContactorFailure','Power failure','Contactor Fault','Contactor Fault - If there is an anomaly with the charger''s contactor, this fault is triggered.','red light'),
  ('ElectricLockFailure','Power failure','Electronic lock Fault- If the electronic lock Fault, such as improper gun insertion causing the lock to jam and the charger to fail to start charging, this malfunction will be triggered','Electronic lock Fault- If the electronic lock Fault, such as improper gun insertion causing the lock to jam and the charger to fail to start charging, this malfunction will be triggered','red light')
