-- =====================================================================
--  Lewden EV Support Hub — database schema
--  Run ONCE in Supabase:  SQL Editor → New query → paste all → Run.
--  Safe to re-run (idempotent); charger/error seeds use ON CONFLICT.
-- =====================================================================

create extension if not exists pgcrypto;

-- ---------- profiles (mirror of auth.users) ----------
create table if not exists profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  full_name text,
  email text,
  created_at timestamptz default now()
);

create or replace function handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $fn$
begin
  values (new.id,
          coalesce(new.raw_user_meta_data->>'full_name', split_part(new.email,'@',1)),
          new.email)
  on conflict (id) do nothing;
  return new;
end; $fn$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function handle_new_user();

-- ---------- generic updated_at touch ----------
create or replace function touch_updated_at() returns trigger
language plpgsql as $fn$
begin new.updated_at = now(); return new; end; $fn$;

-- ---------- error_codes (manufacturer reference) ----------
create table if not exists error_codes (
  code text primary key,
  grade text,
  name text,
  description text,
  light_status text
);

-- ---------- chargers ----------
create table if not exists chargers (
  id uuid primary key default gen_random_uuid(),
  serial_number text unique not null,
  model_no text,
  charger_information text,
  power text,
  connector text,
  certification text,
  batch_no text,
  manufacture_date date,
  handshake_password text,
  lewden_connect_password text,
  firmware_version text,
  notes text,
  status text default 'In field',
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
drop trigger if exists trg_chargers_touch on chargers;
create trigger trg_chargers_touch before update on chargers for each row execute function touch_updated_at();

-- ---------- customers ----------
create table if not exists customers (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  company text, contact text, phone text, email text, address text, installer text, notes text,
  created_by uuid references profiles(id),
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
drop trigger if exists trg_customers_touch on customers;
create trigger trg_customers_touch before update on customers for each row execute function touch_updated_at();

-- ---------- customer_chargers (many-to-many) ----------
create table if not exists customer_chargers (
  customer_id uuid references customers(id) on delete cascade,
  charger_id  uuid references chargers(id)  on delete cascade,
  created_at timestamptz default now(),
  primary key (customer_id, charger_id)
);

-- ---------- tickets ----------
create sequence if not exists ticket_ref_seq start 1;
create table if not exists tickets (
  id uuid primary key default gen_random_uuid(),
  ref text unique,
  customer_id uuid references customers(id) on delete set null,
  charger_id  uuid references chargers(id)  on delete set null,
  title text not null,
  description text,
  status text default 'new',
  priority text default 'medium',
  fault text,
  assigned_to uuid references profiles(id),
  follow_up date,
  created_by uuid references profiles(id),
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create or replace function set_ticket_ref() returns trigger language plpgsql as $fn$
begin
  if new.ref is null then new.ref := 'LEW-' || lpad(nextval('ticket_ref_seq')::text,4,'0'); end if;
  return new;
end; $fn$;
drop trigger if exists trg_ticket_ref on tickets;
create trigger trg_ticket_ref before insert on tickets for each row execute function set_ticket_ref();
drop trigger if exists trg_tickets_touch on tickets;
create trigger trg_tickets_touch before update on tickets for each row execute function touch_updated_at();

-- ---------- ticket_updates ----------
create table if not exists ticket_updates (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid references tickets(id) on delete cascade,
  author uuid references profiles(id),
  body text,
  created_at timestamptz default now()
);

-- ---------- charger_notes ----------
create table if not exists charger_notes (
  id uuid primary key default gen_random_uuid(),
  charger_id uuid references chargers(id) on delete cascade,
  author uuid references profiles(id),
  body text,
  created_at timestamptz default now()
);

-- ---------- visits ----------
create sequence if not exists visit_ref_seq start 1;
create table if not exists visits (
  id uuid primary key default gen_random_uuid(),
  ref text unique,
  date date,
  type text default 'callout',
  customer_ids uuid[] default '{}',
  charger_ids  uuid[] default '{}',
  attended_by  uuid[] default '{}',
  summary text,
  status text default 'open',
  created_by uuid references profiles(id),
  created_at timestamptz default now(),
  updated_at timestamptz default now()
);
create or replace function set_visit_ref() returns trigger language plpgsql as $fn$
begin
  if new.ref is null then new.ref := 'SV-' || lpad(nextval('visit_ref_seq')::text,4,'0'); end if;
  return new;
end; $fn$;
drop trigger if exists trg_visit_ref on visits;
create trigger trg_visit_ref before insert on visits for each row execute function set_visit_ref();
drop trigger if exists trg_visits_touch on visits;
create trigger trg_visits_touch before update on visits for each row execute function touch_updated_at();

-- ---------- visit_records ----------
create table if not exists visit_records (
  id uuid primary key default gen_random_uuid(),
  visit_id uuid references visits(id) on delete cascade,
  charger_id uuid references chargers(id) on delete set null,
  issue text, resolution text, parts text,
  outcome text default 'resolved',
  created_at timestamptz default now()
);

-- ---------- tasks (private to each user) ----------
create table if not exists tasks (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references profiles(id) on delete cascade,
  title text, details text, due date,
  priority text default 'medium',
  done boolean default false,
  created_at timestamptz default now()
);

-- ---------- personal_notes (private) ----------
create table if not exists personal_notes (
  id uuid primary key default gen_random_uuid(),
  user_id uuid references profiles(id) on delete cascade,
  title text, body text,
  pinned boolean default false,
  updated_at timestamptz default now()
);

-- ---------- user_settings (private: theme, layout, etc.) ----------
create table if not exists user_settings (
  user_id uuid primary key references profiles(id) on delete cascade,
  theme text default 'dark',
  accent text default '#209f95',
  compact boolean default false,
  motion boolean default true,
  defs jsonb default '{"priority":"medium","status":"new"}'::jsonb,
  layout jsonb,
  updated_at timestamptz default now()
);

-- =====================================================================
--  Row Level Security
--  Shared tables: any signed-in team member has full access.
--  Private tables: each user sees only their own rows.
-- =====================================================================
alter table profiles          enable row level security;
alter table error_codes       enable row level security;
alter table chargers          enable row level security;
alter table customers         enable row level security;
alter table customer_chargers enable row level security;
alter table tickets           enable row level security;
alter table ticket_updates    enable row level security;
alter table charger_notes     enable row level security;
alter table visits            enable row level security;
alter table visit_records     enable row level security;
alter table tasks             enable row level security;
alter table personal_notes    enable row level security;
alter table user_settings     enable row level security;

-- profiles: everyone signed in can read names; you may edit your own
drop policy if exists profiles_read on profiles;
create policy profiles_read on profiles for select to authenticated using (true);
drop policy if exists profiles_self on profiles;
create policy profiles_self on profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
drop policy if exists profiles_insert_self on profiles;
create policy profiles_insert_self on profiles for insert to authenticated with check (id = auth.uid());

-- shared: read for all signed-in; full write for all signed-in
drop policy if exists error_codes_shared on error_codes;
create policy error_codes_shared on error_codes for all to authenticated using (true) with check (true);
drop policy if exists chargers_shared on chargers;
create policy chargers_shared on chargers for all to authenticated using (true) with check (true);
drop policy if exists customers_shared on customers;
create policy customers_shared on customers for all to authenticated using (true) with check (true);
drop policy if exists customer_chargers_shared on customer_chargers;
create policy customer_chargers_shared on customer_chargers for all to authenticated using (true) with check (true);
drop policy if exists tickets_shared on tickets;
create policy tickets_shared on tickets for all to authenticated using (true) with check (true);
drop policy if exists ticket_updates_shared on ticket_updates;
create policy ticket_updates_shared on ticket_updates for all to authenticated using (true) with check (true);
drop policy if exists charger_notes_shared on charger_notes;
create policy charger_notes_shared on charger_notes for all to authenticated using (true) with check (true);
drop policy if exists visits_shared on visits;
create policy visits_shared on visits for all to authenticated using (true) with check (true);
drop policy if exists visit_records_shared on visit_records;
create policy visit_records_shared on visit_records for all to authenticated using (true) with check (true);

-- private: only the owning user
drop policy if exists tasks_own on tasks;
create policy tasks_own on tasks for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists personal_notes_own on personal_notes;
create policy personal_notes_own on personal_notes for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists user_settings_own on user_settings;
create policy user_settings_own on user_settings for all to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid());

-- =====================================================================
--  Seed: manufacturer error codes
-- =====================================================================
on conflict (code) do nothing;

-- =====================================================================
--  Seed: all 648 chargers from the master serial record
-- =====================================================================
on conflict (serial_number) do nothing;
